import * as rental from "host/rental";
import * as organizer from "host/organizer";
import * as strings from "std/string";

export class RentalOption {
    id: string = "";
    title: string = "";
    specification: string = "";
    totalCents: int = 0;
    price: string = "";
    selected: boolean = false;
}

export class State {
    quantity: int = 1;
    budgetCents: int = 2000;
    search: string = "";
    quantityError: string = "";
    budgetError: string = "";
    valid: boolean = true;
    loading: boolean = false;
    preparing: boolean = false;
    loaded: boolean = false;
    empty: boolean = false;
    rows: RentalOption[] = [];
    selectedId: string | null = null;
    canLoad: boolean = true;
    canPrepare: boolean = false;
    prepared: boolean = false;
    failure: string = "";
    prepareFailure: boolean = false;
    reference: string = "";
    periodStart: string = "2026-10-10T16:00:00Z";
    periodEnd: string = "2026-10-10T22:00:00Z";
}

export class ChangeQuantity {
    value: int = 1;
}

export class ChangeBudget {
    value: int = 2000;
}

export class ChangeSearch {
    value: string = "";
}

export class Load {}

export class Loaded {
    rows: RentalOption[] = [];
    error: string = "";
}

export class Pick {
    value: string = "";
}

export class Prepare {}

export class Prepared {
    success: boolean = false;
    error: string = "";
    reference: string = "";
}

function asciiLower(text: string): string {
    let upper: string = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let lower: string = "abcdefghijklmnopqrstuvwxyz";
    let result: string = "";
    for (let character: string of text) {
        let converted: string = character;
        for (let index: int = 0; index < 26; index = index + 1) {
            if (character === strings.substring(upper, index, index + 1)) {
                converted = strings.substring(lower, index, index + 1);
            }
        }
        result = result + converted;
    }
    return result;
}

function integerText(value: int): string {
    if (value === 0) {
        return "0";
    }
    let digits: string = "0123456789";
    let remaining: int = value;
    let result: string = "";
    while (remaining > 0) {
        let digit: int = remaining % 10;
        result = strings.substring(digits, digit, digit + 1) + result;
        remaining = remaining / 10;
    }
    return result;
}

function euroTotal(cents: int): string {
    let whole: int = cents / 100;
    let fraction: int = cents % 100;
    let fractionText: string = integerText(fraction);
    if (fraction < 10) {
        fractionText = "0" + fractionText;
    }
    return "€ " + integerText(whole) + "." + fractionText + " total";
}

function copyRows(rows: RentalOption[]): RentalOption[] {
    let result: RentalOption[] = [];
    for (let row: RentalOption of rows) {
        let copied: RentalOption = {
            id: row.id,
            title: row.title,
            specification: row.specification,
            totalCents: row.totalCents,
            price: row.price,
            selected: row.selected
        };
        result[result.length] = copied;
    }
    return result;
}

function snapshot(state: State, rows: RentalOption[], selectedId: string | null, loading: boolean, preparing: boolean, loaded: boolean, prepared: boolean, failure: string, prepareFailure: boolean, reference: string): State {
    return {
        quantity: state.quantity,
        budgetCents: state.budgetCents,
        search: state.search,
        quantityError: state.quantityError,
        budgetError: state.budgetError,
        valid: state.valid,
        loading: loading,
        preparing: preparing,
        loaded: loaded,
        empty: loaded && rows.length === 0,
        rows: copyRows(rows),
        selectedId: selectedId,
        canLoad: state.valid && !loading && !preparing,
        canPrepare: state.valid && !loading && !preparing && selectedId !== null && !prepared,
        prepared: prepared,
        failure: failure,
        prepareFailure: prepareFailure,
        reference: reference,
        periodStart: state.periodStart,
        periodEnd: state.periodEnd
    };
}

function unchanged(state: State): State {
    return snapshot(state, state.rows, state.selectedId, state.loading, state.preparing, state.loaded, state.prepared, state.failure, state.prepareFailure, state.reference);
}

function edited(state: State, quantity: int, budget: int, search: string): State {
    let quantityError: string = "";
    let budgetError: string = "";
    if (quantity < 1 || quantity > 8) {
        quantityError = "Enter a quantity from 1 to 8.";
    }
    if (budget < 0 || budget > 100000) {
        budgetError = "Enter a budget from 0 to 100000 cents.";
    }
    let valid: boolean = quantityError === "" && budgetError === "";
    return {
        quantity: quantity,
        budgetCents: budget,
        search: search,
        quantityError: quantityError,
        budgetError: budgetError,
        valid: valid,
        loading: false,
        preparing: false,
        loaded: false,
        empty: false,
        rows: [],
        selectedId: null,
        canLoad: valid,
        canPrepare: false,
        prepared: false,
        failure: "",
        prepareFailure: false,
        reference: "",
        periodStart: state.periodStart,
        periodEnd: state.periodEnd
    };
}

export function initialState(): State {
    return {};
}

// @ui-update
export function changeQuantity(state: State, action: ChangeQuantity): State {
    if (state.loading || state.preparing) {
        return unchanged(state);
    }
    return edited(state, action.value, state.budgetCents, state.search);
}

// @ui-update
export function changeBudget(state: State, action: ChangeBudget): State {
    if (state.loading || state.preparing) {
        return unchanged(state);
    }
    return edited(state, state.quantity, action.value, state.search);
}

// @ui-update
export function changeSearch(state: State, action: ChangeSearch): State {
    if (state.loading || state.preparing) {
        return unchanged(state);
    }
    return edited(state, state.quantity, state.budgetCents, action.value);
}

// @ui-update
export function beginLoad(state: State, action: Load): State {
    if (!state.canLoad) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    return snapshot(state, rows, null, true, false, false, false, "", false, "");
}

// @ui-effect
export async function loadOptions(state: State, action: Load): Loaded {
    try {
        if (!state.valid || state.preparing) {
            return { rows: [], error: "Enter valid inputs before loading options." };
        }
        let records: table[] = await rental.equipment(state.periodStart, state.periodEnd);
        let rows: RentalOption[] = [];
        let query: string = asciiLower(strings.trim(state.search));
        for (let record: table of records) {
            let id: string = record.id;
            let title: string = record.name;
            let specification: string = record.specification;
            let cents: int = record.cents;
            let available: int = record.available;
            let searchable: string = asciiLower(title + " " + specification);
            let matchesRequirement: boolean = strings.contains(searchable, "boom") && strings.contains(searchable, "stand");
            let matchesSearch: boolean = query === "" || strings.contains(searchable, query);
            if (matchesRequirement && matchesSearch && available >= state.quantity && cents >= 0) {
                if (cents <= state.budgetCents / state.quantity) {
                    let total: int = cents * state.quantity;
                    let row: RentalOption = {
                        id: id,
                        title: title,
                        specification: specification,
                        totalCents: total,
                        price: euroTotal(total),
                        selected: false
                    };
                    rows[rows.length] = row;
                }
            }
        }
        return { rows: rows, error: "" };
    } catch (e) {
        return { rows: [], error: "Rental catalogue capability failed: " + e.message };
    }
}

// @ui-update
export function finishLoad(state: State, action: Loaded): State {
    return snapshot(state, action.rows, null, false, false, action.error === "", false, action.error, false, "");
}

// @ui-update
export function pickOption(state: State, action: Pick): State {
    if (state.loading || state.preparing) {
        return unchanged(state);
    }
    let found: boolean = false;
    for (let row: RentalOption of state.rows) {
        if (row.id === action.value) {
            found = true;
        }
    }
    if (!found) {
        return unchanged(state);
    }
    let rows: RentalOption[] = [];
    for (let row: RentalOption of state.rows) {
        let copied: RentalOption = {
            id: row.id,
            title: row.title,
            specification: row.specification,
            totalCents: row.totalCents,
            price: row.price,
            selected: row.id === action.value
        };
        rows[rows.length] = copied;
    }
    return snapshot(state, rows, action.value, false, false, state.loaded, false, "", false, "");
}

// @ui-update
export function beginPrepare(state: State, action: Prepare): State {
    if (!state.canPrepare) {
        return unchanged(state);
    }
    return snapshot(state, state.rows, state.selectedId, false, true, state.loaded, false, "", false, "");
}

// @ui-effect
export async function prepareForReview(state: State, action: Prepare): Prepared {
    try {
        let selectedId: string | null = state.selectedId;
        if (selectedId === null || !state.valid || state.loading) {
            return { success: false, error: "Select a qualifying option before preparing for review.", reference: "" };
        }
        for (let row: RentalOption of state.rows) {
            let optionId: string | null = state.selectedId;
            if (optionId !== null) {
                if (row.id === optionId) {
                    let detail: string = "Item " + row.id + ":" + integerText(state.quantity) + "; from " + state.periodStart + "; until " + state.periodEnd;
                    let result: table = await organizer.stage("rental", "host/rental", row.title, detail, row.price, state.periodEnd);
                    let staged: boolean = result.staged;
                    let reference: string = result.reference;
                    if (!staged) {
                        return { success: false, error: "Organizer capability did not prepare the descriptor. Retry preparation.", reference: "" };
                    }
                    return { success: true, error: "", reference: reference };
                }
            }
        }
        return { success: false, error: "The selected option is no longer in the shortlist. Load options again.", reference: "" };
    } catch (e) {
        return { success: false, error: "Organizer preparation capability failed: " + e.message, reference: "" };
    }
}

// @ui-update
export function finishPrepare(state: State, action: Prepared): State {
    return snapshot(state, state.rows, state.selectedId, state.loading, false, state.loaded, action.success, action.error, !action.success, action.reference);
}

export function main(): null {
    return null;
}

