import * as app from "./experience";
import * as ui from "./platform.dealui-pack";

// @ui-root
export view RentalShortlist(state: app.State): View {
    ui.Column() {
        ui.Text(value: "Rental shortlist")
        ui.Text(value: "Boom stand · Adjustable boom")
        ui.Text(value: "2026-10-10T16:00:00Z to 2026-10-10T22:00:00Z")
        ui.Card() {
            ui.IntField(value: state.quantity, label: "Quantity", minimum: 0, maximum: 9, step: 1, enabled: !state.loading && !state.preparing, supporting: "Only quantities from 1 to 8 are valid. Editing clears options, selection and preparation.", error: state.quantityError, onChange: action app.ChangeQuantity { value: payload }, accessibilityLabel: "Quantity")
            ui.IntField(value: state.budgetCents, label: "Total budget in cents", minimum: 0, maximum: 100000, step: 100, enabled: !state.loading && !state.preparing, supporting: "Total budget for all units, from 0 to 100000 cents. Editing invalidates the selection.", error: state.budgetError, onChange: action app.ChangeBudget { value: payload }, accessibilityLabel: "Budget")
            ui.SearchField(value: state.search, label: "Search", multiline: false, enabled: !state.loading && !state.preparing, supporting: "Search is restricted to boom stands: both boom and stand must occur in the name/specification. Your trimmed, ASCII-lowercased text adds a substring filter; empty accepts all qualifying stands. Editing clears the selection.", error: "", onChange: action app.ChangeSearch { value: payload }, accessibilityLabel: "Search")
            ui.Button(text: "Load options", enabled: state.canLoad, onClick: action app.Load {}, accessibilityLabel: "Load options")
        }
        When(state.loading) {
            ui.Progress(label: "Loading")
        }
        When(state.failure !== "") {
            When(state.prepareFailure) {
                ui.Failure(text: state.failure, onRetry: action app.Prepare {}, accessibilityLabel: "Retry preparation for native review")
            } Else {
                ui.Failure(text: state.failure, onRetry: action app.Load {}, accessibilityLabel: "Retry loading rental options")
            }
        }
        When(state.empty) {
            ui.Text(value: "No qualifying options")
            ui.Text(value: "Try a different search, quantity or total budget. Results must match both boom and stand and have enough available units.")
        }
        When(!state.loaded && !state.loading && state.failure === "") {
            ui.Text(value: "Enter valid inputs, then load the period catalogue. No provider is contacted until you load options.")
        }
        ForEach(state.rows, row: app.RentalOption, key: row.id) {
            ui.Option(value: row.id, title: row.title, detail: row.specification, price: row.price, meta: "Total price for the requested quantity and disclosed period", selected: row.selected, enabled: !state.loading && !state.preparing, onSelect: action app.Pick { value: payload }, accessibilityLabel: row.title)
        }
        ui.Card() {
            ui.Text(value: "Native review preparation")
            ui.Text(value: "Select an option to prepare a local descriptor. This does not reserve equipment or confirm a rental.")
            ui.Button(text: "Prepare for review", enabled: state.canPrepare, onClick: action app.Prepare {}, accessibilityLabel: "Prepare for review")
            When(state.preparing) {
                ui.Progress(label: "Preparing for native review")
            }
            When(state.prepared) {
                ui.Notice(text: "Prepared for native review", tone: "info")
                ui.Text(value: "Your selection is preserved. Native permission and confirmation remain outside this shortlist.")
            }
        }
    }
}
